<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { opcApi } from '@/api/opc'

type Inquiry={id:string;customer:string;customer_id?:string;source:string;raw_text:string;product_type:string;specs:Record<string,any>;status:string;confidence:number;created_at:string}
const emit=defineEmits<{quote:[Inquiry]}>()
const useMock=import.meta.env.VITE_USE_MOCK==='true';const search=ref('');const statusFilter=ref('');const dialog=ref(false);const detailDialog=ref(false);const editingId=ref('');const selected=ref<Inquiry|null>(null)
const customerOptions=ref([{id:'c1',name:'河北安筑工程'},{id:'c2',name:'Nordic Fence AB'},{id:'c3',name:'山东海岳矿业'}])
const statuses=['NEW','PARSING','NEEDS_REVIEW','READY_TO_QUOTE','QUOTED','CLOSED'];const statusLabels:Record<string,string>={NEW:'新询盘',PARSING:'识别中',NEEDS_REVIEW:'待确认',READY_TO_QUOTE:'可报价',QUOTED:'已报价',CLOSED:'已关闭'}
const inquiries=ref<Inquiry[]>([
  {id:'INQ-20250922001',customer:'河北安筑工程',customer_id:'c1',source:'企业微信',raw_text:'建筑工地临边防护网，热镀锌，3.5mm 丝径，50×50mm 网孔，共 2000 平方米。',product_type:'welded_mesh',specs:{material:'low_carbon_steel',wire_diameter_mm:3.5,mesh_size_mm:50,quantity_area_m2:2000,surface_treatment:'hot_dip_galvanized'},status:'NEEDS_REVIEW',confidence:.86,created_at:'今天 10:24'},
  {id:'INQ-20250922002',customer:'Nordic Fence AB',source:'邮件',raw_text:'Need farm fence rolls, PVC coated, please quote CIF Gothenburg.',product_type:'fence_mesh',specs:{surface_treatment:'pvc_coated'},status:'PARSING',confidence:.62,created_at:'今天 09:48'},
  {id:'INQ-20250921018',customer:'山东海岳矿业',source:'网站',raw_text:'不锈钢矿筛网，需材质报告。',product_type:'screen_mesh',specs:{material:'stainless_304'},status:'READY_TO_QUOTE',confidence:.94,created_at:'昨天'},
])
const form=reactive({customer:'',customer_id:'',source:'企业微信',raw_text:'',product_type:'welded_mesh',status:'NEW',confidence:0,specs_text:'{}'})
const filtered=computed(()=>inquiries.value.filter(x=>(!search.value||`${x.id}${x.customer}${x.raw_text}${x.product_type}`.toLowerCase().includes(search.value.toLowerCase()))&&(!statusFilter.value||x.status===statusFilter.value)))
onMounted(async()=>{if(useMock)return;try{const[inquiryRes,customerRes]=await Promise.all([opcApi.listInquiries(),opcApi.listCustomers()]);customerOptions.value=customerRes.data.map((x:any)=>({id:x.id,name:x.name}));inquiries.value=inquiryRes.data.map((x:any)=>({...x,customer:customerOptions.value.find(c=>c.id===x.customer_id)?.name||'未关联客户',created_at:x.created_at?.slice(0,16)||''}))}catch{ElMessage.warning('询盘数据加载失败，已保留演示数据')}})
function reset(){Object.assign(form,{customer:'',customer_id:'',source:'企业微信',raw_text:'',product_type:'welded_mesh',status:'NEW',confidence:0,specs_text:'{}'})}
function openCreate(){editingId.value='';reset();dialog.value=true}
function openEdit(x:Inquiry){editingId.value=x.id;Object.assign(form,{...x,specs_text:JSON.stringify(x.specs,null,2),confidence:Math.round(x.confidence*100)});dialog.value=true}
function openDetail(x:Inquiry){selected.value=x;detailDialog.value=true}
async function save(){form.customer=customerOptions.value.find(x=>x.id===form.customer_id)?.name||form.customer;if(!form.customer||!form.raw_text)return ElMessage.warning('请填写客户和询盘内容');let specs={};try{specs=JSON.parse(form.specs_text||'{}')}catch{return ElMessage.error('规格 JSON 格式错误')};const payload={customer_id:form.customer_id||undefined,source:form.source,raw_text:form.raw_text,product_type:form.product_type,specs,status:form.status,confidence:form.confidence/100};if(editingId.value){if(!useMock)await opcApi.updateInquiry(editingId.value,payload);const x=inquiries.value.find(x=>x.id===editingId.value);if(x)Object.assign(x,payload,{customer:form.customer})}else{const id=useMock?`INQ-${Date.now()}`:(await opcApi.createInquiry(payload)).data.id;inquiries.value.unshift({id,customer:form.customer,created_at:'刚刚',...payload})}dialog.value=false;ElMessage.success('询盘已保存')}
async function remove(x:Inquiry){await ElMessageBox.confirm(`确认删除询盘 ${x.id}？`,'删除询盘',{type:'warning'});if(!useMock)await opcApi.deleteInquiry(x.id);inquiries.value=inquiries.value.filter(i=>i.id!==x.id);ElMessage.success('询盘已删除')}
function advance(x:Inquiry){const i=statuses.indexOf(x.status);if(i<statuses.length-1)x.status=statuses[i+1];ElMessage.success(`询盘状态更新为：${statusLabels[x.status]}`)}
function toQuote(x:Inquiry){x.status='QUOTED';emit('quote',x);ElMessage.success('询盘参数已带入报价流程')}
defineExpose({openCreate})
</script>

<template><div>
  <div class="stats"><article><span>待处理询盘</span><strong>{{ inquiries.filter(x=>!['QUOTED','CLOSED'].includes(x.status)).length }}</strong><em>需要关注</em></article><article><span>待人工确认</span><strong>{{ inquiries.filter(x=>x.status==='NEEDS_REVIEW').length }}</strong><em>低置信度字段</em></article><article><span>可立即报价</span><strong>{{ inquiries.filter(x=>x.status==='READY_TO_QUOTE').length }}</strong><em>规格已完整</em></article><article><span>平均置信度</span><strong>{{ Math.round(inquiries.reduce((s,x)=>s+x.confidence,0)/inquiries.length*100) }}%</strong><em>AI 提取质量</em></article></div>
  <section class="card"><header><h3>询盘列表</h3><div><el-input v-model="search" placeholder="搜索编号、客户或需求" :prefix-icon="'Search'" clearable/><el-select v-model="statusFilter" placeholder="全部状态" clearable><el-option v-for="s in statuses" :key="s" :label="statusLabels[s]" :value="s"/></el-select><el-button type="primary" @click="openCreate"><el-icon><Plus/></el-icon>新增询盘</el-button></div></header><div class="table"><div class="row head"><span>询盘/客户</span><span>来源</span><span>产品</span><span>AI置信度</span><span>状态</span><span>时间</span><span>操作</span></div><div v-for="x in filtered" :key="x.id" class="row"><div><b class="inq-id">{{ x.id }}</b><small>{{ x.customer }}</small></div><span>{{ x.source }}</span><span>{{ x.product_type }}</span><div class="confidence"><i><em :style="{width:(x.confidence*100)+'%'}"></em></i><b>{{ Math.round(x.confidence*100) }}%</b></div><em :class="x.status">{{ statusLabels[x.status] }}</em><span>{{ x.created_at }}</span><div class="actions"><button @click="openDetail(x)">详情</button><button @click="advance(x)">推进</button><button v-if="['NEEDS_REVIEW','READY_TO_QUOTE'].includes(x.status)" class="quote" @click="toQuote(x)">转报价</button><button @click="openEdit(x)">编辑</button><button class="danger" @click="remove(x)">删除</button></div></div></div></section>
  <el-dialog v-model="dialog" :title="editingId?'编辑询盘':'新增询盘'" width="680px"><el-form label-position="top"><div class="form-grid"><el-form-item label="客户"><el-select v-model="form.customer_id" filterable allow-create default-first-option><el-option v-for="x in customerOptions" :key="x.id" :label="x.name" :value="x.id"/></el-select></el-form-item><el-form-item label="来源"><el-select v-model="form.source"><el-option label="企业微信" value="企业微信"/><el-option label="邮件" value="邮件"/><el-option label="网站" value="网站"/><el-option label="WhatsApp" value="WhatsApp"/></el-select></el-form-item><el-form-item label="产品类型"><el-select v-model="form.product_type"><el-option label="焊接网" value="welded_mesh"/><el-option label="护栏网" value="fence_mesh"/><el-option label="六角网" value="hexagonal_mesh"/><el-option label="工业筛网" value="screen_mesh"/></el-select></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option v-for="s in statuses" :key="s" :label="statusLabels[s]" :value="s"/></el-select></el-form-item><el-form-item label="AI置信度（%）"><el-input-number v-model="form.confidence" :min="0" :max="100"/></el-form-item><el-form-item label="询盘原文" class="wide"><el-input v-model="form.raw_text" type="textarea" :rows="4"/></el-form-item><el-form-item label="结构化规格 JSON" class="wide"><el-input v-model="form.specs_text" type="textarea" :rows="5"/></el-form-item></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog>
  <el-dialog v-model="detailDialog" title="询盘详情" width="660px"><div v-if="selected" class="detail"><header><div><b>{{ selected.id }}</b><span>{{ selected.customer }} · {{ selected.source }}</span></div><em :class="selected.status">{{ statusLabels[selected.status] }}</em></header><h4>客户原始需求</h4><p>{{ selected.raw_text }}</p><h4>AI 提取规格</h4><dl><div v-for="(value,key) in selected.specs" :key="key"><dt>{{ key }}</dt><dd>{{ value }}</dd></div></dl></div><template #footer><el-button @click="detailDialog=false">关闭</el-button><el-button @click="selected&&openEdit(selected);detailDialog=false">编辑规格</el-button><el-button v-if="selected" type="primary" @click="toQuote(selected);detailDialog=false">转为报价</el-button></template></el-dialog>
</div></template>

<style scoped>
.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin-bottom:18px}.stats article,.card{background:#fff;border:1px solid #e2eaf2;border-radius:12px;box-shadow:0 5px 18px rgba(23,47,79,.045)}.stats article{padding:17px}.stats span,.stats em{display:block;color:#8593a5;font-size:9px}.stats strong{display:block;font-size:22px;color:#203249;margin:5px 0}.stats em{font-style:normal;color:#25a37e}.card{padding:18px}.card>header{display:flex;justify-content:space-between;align-items:center;margin-bottom:12px}.card h3{margin:0;font-size:15px}.card>header>div{display:flex;gap:8px}.card>header .el-input{width:240px}.card>header .el-select{width:120px}.row{display:grid;grid-template-columns:1.2fr .55fr .75fr .8fr .65fr .6fr 1.45fr;gap:11px;align-items:center;min-height:61px;border-top:1px solid #edf1f5;color:#596b80;font-size:9px}.row.head{min-height:34px;border:0;color:#96a1ae}.row b,.row small{display:block}.row small{margin-top:3px;color:#95a2af}.inq-id{color:#286fd1}.confidence{display:flex;align-items:center;gap:6px}.confidence i{width:55px;height:5px;background:#edf2f6;border-radius:3px;overflow:hidden}.confidence i em{display:block;height:100%;background:#22ac84}.row>em,.detail header em{width:fit-content;font-style:normal;padding:4px 7px;border-radius:10px;background:#edf2f7;color:#61758c}.row>em.NEEDS_REVIEW,.detail header em.NEEDS_REVIEW{background:#fff0dc;color:#bf711e}.row>em.READY_TO_QUOTE{background:#e7f7f1;color:#168262}.row>em.PARSING{background:#eaf2ff;color:#286fd0}.actions{display:flex;gap:3px;flex-wrap:wrap}.actions button{border:0;background:#edf4ff;color:#286ed0;border-radius:4px;padding:5px 6px;font-size:8px;cursor:pointer}.actions .quote{background:#e5f7f0;color:#138260}.actions .danger{background:#fff0ef;color:#d65b4c}.form-grid{display:grid;grid-template-columns:1fr 1fr;gap:0 16px}.form-grid .wide{grid-column:1/-1}.form-grid .el-select,.form-grid .el-input-number{width:100%}.detail header{display:flex;justify-content:space-between}.detail header span{display:block;font-size:10px;color:#8391a3;margin-top:4px}.detail h4{font-size:11px;margin:18px 0 7px}.detail>p{background:#f6f8fb;padding:12px;border-radius:7px;color:#52677d;font-size:10px;line-height:1.7}.detail dl{display:grid;grid-template-columns:1fr 1fr;border:1px solid #e3eaf1;border-radius:8px;overflow:hidden}.detail dl div{display:grid;grid-template-columns:1fr 1fr;border-bottom:1px solid #e9edf3}.detail dt,.detail dd{margin:0;padding:8px;font-size:9px}.detail dt{background:#f7f9fc;color:#7a899b}@media(max-width:950px){.stats{grid-template-columns:1fr 1fr}.table{overflow:auto}.row{min-width:950px}}@media(max-width:600px){.stats,.form-grid{grid-template-columns:1fr}.card>header{flex-direction:column;align-items:flex-start;gap:10px}.card>header>div{flex-wrap:wrap}.card>header .el-input,.card>header .el-select{width:100%}}
</style>
